"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["25245"],{99029(a){a.exports=JSON.parse('{"id":"FIN-1353","slug":"data-table","term":"Data Table","also_known_as":[],"difficulty":"Advanced","definition":"A data table is a spreadsheet tool that automatically recalculates a model\'s result for a range of different input values, displaying the outcomes in a grid.","explanation":["Data tables allow analysts to see how changes in one or two key inputs affect an output, without manually changing the inputs and recording results each time. They are the most common way to build sensitivity tables in financial models.","A one-variable data table shows how an output changes as one input varies. A two-variable data table shows the result for every combination of two inputs, with one input across the top and the other down the side.","For example, a valuation model might use a two-variable data table to show the value per share for discount rates from 8% to 10% across the top and long-term growth rates from 1.5% to 3% down the side.","Data tables update automatically when the model changes, which makes them powerful. But large data tables can slow down spreadsheets significantly, because the model is recalculated for every cell. They also require the inputs to be on the same sheet as the table in some spreadsheet programs, which can affect model layout."],"note":"","total":1725,"prev":{"slug":"data-snooping","term":"Data Snooping"},"next":{"slug":"data-visualization","term":"Data Visualization"}}')}}]);